/** 이름을 가진 항목 목록에서 id → name 을 뽑는다 (모양이 다르면 건너뛴다) */
function collect(into: Map<string, string>, list: unknown): void {
  if (!Array.isArray(list)) return;
  for (const e of list) {
    if (!e || typeof e !== 'object') continue;
    const { id, name } = e as { id?: unknown; name?: unknown };
    if (typeof id === 'string' && typeof name === 'string' && !into.has(id)) into.set(id, name);
  }
}

/**
 * 이름표 만들기. recipes 는 결과물 하나짜리 레시피의 out 키 = 레시피 이름으로 본다.
 * potions 의 ingredients/modifiers 는 { id: { name } } 모양.
 */
export function buildItemNames(sources: { recipes?: unknown; dragons?: unknown; potions?: unknown; extra?: ReadonlyMap<string, string> }): Map<string, string> {
  const names = new Map<string, string>();
  if (sources.extra) for (const [id, name] of sources.extra) names.set(id, name); // 자동 생성 아이템 (전투 장비, M8-2)
  const rec = (sources.recipes as { recipes?: unknown } | undefined)?.recipes;
  if (Array.isArray(rec)) {
    for (const r of rec) {
      if (!r || typeof r !== 'object') continue;
      const { out, name } = r as { out?: Record<string, unknown>; name?: unknown };
      if (!out || typeof name !== 'string') continue;
      const keys = Object.keys(out);
      if (keys.length === 1 && !names.has(keys[0])) names.set(keys[0], name);
    }
  }
  collect(names, (sources.dragons as { materials?: unknown } | undefined)?.materials);
  const pot = sources.potions as { ingredients?: Record<string, unknown>; modifiers?: Record<string, unknown> } | undefined;
  for (const table of [pot?.ingredients, pot?.modifiers]) {
    if (!table) continue;
    for (const [id, v] of Object.entries(table)) {
      if (id.startsWith('_') || names.has(id)) continue;
      const name = (v as { name?: unknown } | null)?.name;
      if (typeof name === 'string') names.set(id, name);
    }
  }
  for (const [id, name] of Object.entries(ITEM_FALLBACK_KO)) if (!names.has(id)) names.set(id, name);
  return names;
}

/** 아이템 한국어 이름: 블록이면 블록 이름, 아니면 모은 이름표, 없으면 id 그대로 */
// ---------------------------------------------------------------- 인챈트 (#231)

/** 인챈트가 붙은 아이템 id: `iron_sword.ench.sharpness.2` — 하나만 붙는다 */
export const ENCH_SEP = '.ench.';
export const ROMAN = ['', 'I', 'II', 'III', 'IV', 'V'] as const;
export function encodeEnchanted(base: string, ench: string, level: number): string {
  return `${base}${ENCH_SEP}${ench}.${level}`;
}
export function parseEnchanted(item: string | null | undefined): { base: string; ench: string; level: number } | null {
  if (!item) return null;
  const i = item.indexOf(ENCH_SEP);
  if (i < 0) return null;
  const rest = item.slice(i + ENCH_SEP.length);
  const j = rest.lastIndexOf('.');
  if (j < 0) return null;
  const level = Number(rest.slice(j + 1));
  if (!Number.isInteger(level) || level < 1) return null;
  return { base: item.slice(0, i), ench: rest.slice(0, j), level };
}
/** 인챈트를 뗀 원래 아이템 id (안 붙어 있으면 그대로) */
export function baseItemOf(item: string): string {
  return parseEnchanted(item)?.base ?? item;
}
/** 이 아이템에 붙은 그 인챈트의 단계 (없으면 0) */
export function enchantLevelOf(item: string | null | undefined, ench: string): number {
  const e = parseEnchanted(item);
  return e && e.ench === ench ? e.level : 0;
}

export function itemName(id: string, registry: BlockRegistry, names: ReadonlyMap<string, string>): string {
  const e = parseEnchanted(id);
  if (e) return `${itemName(e.base, registry, names)} ✨${names.get('ench.' + e.ench) ?? e.ench} ${ROMAN[e.level] ?? e.level}`; // 인챈트 이름은 data.ts 가 'ench.<id>' 로 넣는다 (#231)
  return registry.find(id)?.name ?? names.get(id) ?? id;
}

// ---------------------------------------------------------------- 아이템 ↔ 블록 (M4, 결정 #66)


export const BUCKET = 'bucket';
export const WATER_BUCKET = 'water_bucket';
export const LAVA_BUCKET = 'lava_bucket';

/** 손에 든 아이템으로 놓을 수 있는 블록 번호. 못 놓는 아이템이면 null */
export function itemToBlock(item: string, registry: BlockRegistry): number | null {
  if (item === WATER_BUCKET) {
    const w = registry.find('water');
    return w ? registry.fluidFinite(w.num, FLUID_FULL) : null;
  }
  if (item === LAVA_BUCKET) {
    const l = registry.find('lava');
    return l ? registry.fluidFinite(l.num, FLUID_FULL) : null;
  }
  const crop = registry.defs.find((b) => b.seed === item); // 씨앗을 들면 작물 싹을 놓는다 (#165)
  if (crop) return crop.num;
  const d = registry.find(item);
  if (!d || d.internal || d.fluid || d.num === 0) return null;
  return d.num;
}

/** 이 블록을 놓으려면 가방에서 무엇이 나가나 (놓는 블록 id → 아이템 id). 놓을 수 없으면 null */
export function itemForPlacing(blockId: string, registry: BlockRegistry): string | null {
  const d = registry.find(blockId);
  if (!d || d.num === 0) return null;
  if (d.fluid) return d.fluidVolume === FLUID_FULL ? (d.fluid === 'water' ? WATER_BUCKET : LAVA_BUCKET) : null;
  if (d.door) return d.door.upper || d.door.open ? null : registry.get(d.door.base).id; // 문은 아래·닫힘 변형을 놓을 때 문 아이템 하나
  if (d.torch) return registry.get(d.torch.base).id; // 벽에 붙인 횃불도 횃불 아이템 하나 (#82)
  if (d.rail) return registry.get(d.rail.base).id; // 굽은 철도도 철도 아이템 하나 (#237)
  if (d.stairs) return registry.get(d.stairs.base).id; // 어느 쪽을 보든·뒤집혔든 계단 아이템 하나 (#291)
  if (d.ladder) return registry.get(d.ladder.base).id; // 어느 벽에 붙였든 사다리 하나 (#299)
  if (d.trap) return d.trap.open ? null : registry.get(d.trap.base).id; // 다락문은 닫힌 것을 놓을 때 하나 (#296)
  if (d.gate) return d.gate.open ? null : registry.get(d.gate.base).id; // 울타리문은 닫힌 것을 놓을 때 문 하나 (#295)
  if (d.slab) return registry.get(d.slab.base).id; // 위 반이든, 놓인 반 블록에 하나를 더 얹어 한 칸을 만들든 반 블록 아이템 하나 (#292)
  if (d.chest) return registry.get(d.chest.base).id; // 큰 상자 반쪽도 상자 아이템 하나 (#84)
  if (d.bed) return d.bed.head ? null : registry.get(d.bed.base).id; // 침대는 발 쪽을 놓을 때 침대 아이템 하나 (#188)
  if (d.seed) return d.seed; // 작물 싹은 씨앗 아이템으로 심는다 (#165)
  return d.internal ? null : d.id;
}

/**
 * 블록을 부수면(또는 액체를 떠내면) 무엇이 나오나. 액체 가득한 칸은 양동이가 있어야 하고(needsBucket) 양동이가 찬 것으로 바뀐다.
 * dropCount 범위는 자리·시드로 결정론적으로 뽑는다. 아무것도 안 나오면 null.
 * bonusDrops 가 있으면 덤(bonus)도 같이 — 발광석은 블록 1개 + 가루 0~3개 (아빠 2026-09-19)
 */
export interface Drop {
  item: string;
  count: number;
  needsBucket: boolean;
  /** 덤으로 같이 나오는 것. 개수 0 이 뽑히면 없음(undefined) */
  bonus?: { item: string; count: number };
}

export function dropOf(def: BlockDef, x: number, y: number, z: number, seed: number): Drop | null {
  if (def.fluid) {
    if (def.fluidLevel !== 0) return null; // 얕은 웅덩이·흐름은 닦아낼 뿐
    return { item: def.fluid === 'water' ? WATER_BUCKET : LAVA_BUCKET, count: 1, needsBucket: true };
  }
  if (!def.drops) return null;
  const n = pick(def.dropCount, x, y, z, seed);
  if (n <= 0) return null;
  const drop: Drop = { item: def.drops, count: n, needsBucket: false };
  if (def.bonusDrops) {
    const b = pick(def.bonusCount, x, y, z, seed ^ 0x5bd1e995); // 본 드롭과 다른 수
    if (b > 0) drop.bonus = { item: def.bonusDrops, count: b };
  }
  return drop;
}

function pick([lo, hi]: readonly [number, number], x: number, y: number, z: number, seed: number): number {
  return hi > lo ? lo + Math.floor(hash3(x, y, z, seed) * (hi - lo + 1)) : lo;
}
