/**
 * data/expeditions.json 검증·로드 + 원정 시간 규칙 (M3).
 * 아들이 편집하는 파일이므로 실패 메시지는 짧고 쉬운 한국어로 낸다.
 * 낮·저녁·밤 단계와 스카이라이트 배율은 순수 함수 — 클라(하늘·안개)와 서버(위험도, M7)가 같은 값을 쓴다.
 */
import { z } from 'zod';
import { hash3 } from '../math/prng';
import { DataError, koreanizeMessage } from './blocks';
import { WILD_KINDS } from './mobs';

const NAME_RE = /^[a-z0-9_]+$/;

const RawExpedition = z
  .object({
    id: z.string().regex(NAME_RE, '영문 소문자·숫자·밑줄(_)만 쓸 수 있어요 (예: grass_island)'),
    name: z.string().min(1, '한국어 이름이 비어 있어요'),
    generator: z.string().min(1, '어떤 생성기를 쓰는지 적어 주세요 (island, cave, desert …)'),
    durationSec: z.number().int().positive('0보다 커야 해요 (초)'),
    nightStartsAt: z.number().int().min(0, '0 이상이어야 해요 (0 = 항상 어두움)'),
    treasures: z.number().int().min(0, '0 이상이어야 해요'),
    unlockedBy: z.string().min(1),
    nightMobs: z.array(z.string()).optional(),
    /** 사냥 동물 (2026-11-05): 동물 id → 몇 마리. 처음부터 무리로 돌아다닌다 */
    wildAnimals: z.record(z.string(), z.number().int().min(0, '0 이상이어야 해요').max(20, '한 종류는 20마리까지예요')).optional(),
    /** 팬텀이 오는 곳 (2026-11-07): 하늘이 트인 오버월드 원정지. 침대에서 오래 안 잔 사람에게 밤에 */
    phantoms: z.boolean().optional(),
    /** 처음부터 곳곳에 서 있는 몹 수 (2026-11-07 아빠 "원정에 중간중간 몹들을 넣어줘") — 없으면 ROAMERS_DEFAULT, 0 이면 없음 */
    roamers: z.number().int().min(0, '0 이상이어야 해요').max(30, '30마리까지예요').optional(),
    danger: z.number().int().min(0, '0 이상이어야 해요').max(10, '0~10 사이여야 해요'),
    materials: z.array(z.string()),
    release: z.string().optional(),
    /** 이 원정지만의 상자 보너스 (#159): extraPicks 번 더 뽑고, always 는 상자마다 꼭 들어간다 */
    /** 항상 어두운 곳(nightStartsAt 0)의 바탕 빛 0~1 — 엔드는 0.5 로 어둑하게, 동굴·네더는 안 적으면 한밤(0.22) (#162) */
    skyLight: z.number().min(0, '0~1 사이여야 해요').max(1, '0~1 사이여야 해요').optional(),
    /** 이 원정지의 보스 (bosses.json id). 생성기가 자리(den)를 주면 서버가 거기에 세운다 (#162) */
    boss: z.object({ id: z.string() }).loose().optional(),
    treasureBonus: z
      .object({
        extraPicks: z.number().int().min(0, '0 이상이어야 해요').optional(),
        always: z.array(z.object({ item: z.string(), min: z.number().int().min(0), max: z.number().int().min(1), chance: z.number().min(0, '0 이상이어야 해요').max(1, '1 이하여야 해요 (1 = 꼭)').optional() }).loose()).optional(),
      })
      .loose()
      .optional(),
  })
  .loose(); // 아들 디테일(sonDetails 등)은 그대로 통과

const ExpeditionsFile = z
  .object({
    _comment: z.string().optional(),
    returnGraceSec: z.number().int().min(0, '0 이상이어야 해요'),
    failedReturnKeepRatio: z.number().min(0, '0~1 사이여야 해요').max(1, '0~1 사이여야 해요'),
    minStartMarginMin: z.number().min(0, '0 이상이어야 해요'),
    treasureChestLoot: z
      .object({
        picks: z.number().int().min(1, '1 이상이어야 해요'),
        pool: z.array(z.object({ item: z.string(), min: z.number().int().min(0), max: z.number().int().min(1), weight: z.number().positive() }).loose()).min(1, '보상이 하나는 있어야 해요'),
      })
      .loose()
      .optional(),
    expeditions: z.array(RawExpedition).min(1, '원정지가 하나도 없어요'),
  })
  .loose();

const FIELD_KO: Record<string, string> = {
  id: 'id(영문 이름)',
  name: 'name(한국어 이름)',
  generator: 'generator(지형 생성기)',
  durationSec: 'durationSec(원정 시간, 초)',
  nightStartsAt: 'nightStartsAt(밤 시작, 초)',
  treasures: 'treasures(보물 상자 수)',
  unlockedBy: 'unlockedBy(여는 포탈 단계)',
  danger: 'danger(위험도)',
  materials: 'materials(나오는 재료)',
  release: 'release(버전)',
};

/** 원정 곳곳에 처음부터 서 있는 몹 (2026-11-07 아빠 "원정에 중간중간 몹들을 넣어줘"): expeditions.json roamers 가 없으면 이만큼 */
export const ROAMERS_DEFAULT = 10;

export interface ExpeditionDef {
  readonly id: string;
  readonly name: string;
  readonly generator: string;
  readonly durationSec: number;
  /** 밤이 시작되는 초. 0 = 처음부터 어두움(동굴·네더·엔드) */
  readonly nightStartsAt: number;
  readonly treasures: number;
  readonly unlockedBy: string;
  /** 밤에 나오는 몹 (mobs.ts 가 아는 것만 쓴다 — 첫째가 셋에 둘, 나머지가 셋에 하나) */
  readonly nightMobs: readonly string[];
  /** 사냥 동물 (2026-11-05, mobs.ts WILD_KINDS) → 마릿수. 없으면 {} */
  readonly wildAnimals: Readonly<Record<string, number>>;
  /** 팬텀이 오는 곳 (2026-11-07) */
  readonly phantoms: boolean;
  /** 처음부터 곳곳에 서 있는 몹 수 (2026-11-07) */
  readonly roamers: number;
  /** 상자 보너스 (#159, 사막) — 없으면 공용 규칙만 */
  readonly treasureBonus: TreasureBonus | null;
  /** 보스 몹 id (expeditions.json boss.id). 없으면 null */
  readonly bossId: string | null;
  /** 항상 어두운 곳의 바탕 빛 (없으면 NIGHT_SKY) */
  readonly skyLight: number | null;
  readonly danger: number;
  readonly materials: readonly string[];
  readonly release: string;
}

export interface ExpeditionRules {
  /** 원정이 끝난 뒤 세계를 몇 초 더 두나(늦은 귀환·정산 전송) */
  readonly returnGraceSec: number;
  /** 늦게(또는 못) 돌아오면 가져오는 비율 */
  readonly failedReturnKeepRatio: number;
  /** 원정 시간 + 이 여유(분)가 남아야 출발할 수 있다 (M5 시간 규칙) */
  readonly minStartMarginMin: number;
  /** 보물 상자 랜덤 보상 (#117): pool 에서 picks 가지, 원정 시드·상자 번호로 결정론 */
  readonly treasureChestLoot: TreasureLootRules;
}

export interface TreasureLootEntry {
  readonly item: string;
  readonly min: number;
  readonly max: number;
  readonly weight: number;
}
export interface TreasureLootRules {
  readonly picks: number;
  readonly pool: readonly TreasureLootEntry[];
}
export interface TreasureBonus {
  readonly extraPicks: number;
  /** chance (0~1, 없으면 1 = 꼭): 상자마다 이 확률로만 들어간다 (#217 다이아몬드) */
  readonly always: readonly { item: string; min: number; max: number; chance: number }[];
}

/** 상자 index 의 보상 (결정론). 같은 종류는 한 번만, pool 이 모자라면 그만큼만 */
export function treasureLoot(rules: TreasureLootRules, seed: number, index: number, picks = rules.picks): { item: string; count: number }[] {
  const out: { item: string; count: number }[] = [];
  const used = new Set<number>();
  const total = rules.pool.reduce((a, e) => a + e.weight, 0);
  for (let k = 0; k < picks && used.size < rules.pool.length; k++) {
    let pick = -1;
    for (let attempt = 0; attempt < 16 && pick < 0; attempt++) {
      let r = hash3(index, k * 16 + attempt, 51, seed) * total;
      for (let i = 0; i < rules.pool.length; i++) {
        r -= rules.pool[i]!.weight;
        if (r <= 0) {
          if (!used.has(i)) pick = i;
          break;
        }
      }
    }
    if (pick < 0) pick = rules.pool.findIndex((_, i) => !used.has(i));
    used.add(pick);
    const e = rules.pool[pick]!;
    const count = e.min + Math.floor(hash3(index, k, 52, seed) * (Math.max(e.min, e.max) - e.min + 1));
    if (count > 0) out.push({ item: e.item, count });
  }
  return out;
}

/** 원정지 보너스까지 더한 상자 보상 (#159): extraPicks 만큼 더 뽑고, always 는 꼭 넣는다(이미 뽑힌 것이면 개수를 더한다). chance 가 1 보다 작으면 그 확률로만 (#217) */
export function treasureLootFor(rules: TreasureLootRules, def: Pick<ExpeditionDef, 'treasureBonus'>, seed: number, index: number): { item: string; count: number }[] {
  const bonus = def.treasureBonus;
  if (!bonus) return treasureLoot(rules, seed, index);
  const out = treasureLoot(rules, seed, index, rules.picks + bonus.extraPicks);
  bonus.always.forEach((a, j) => {
    if (a.chance < 1 && hash3(index, 200 + j, 54, seed) >= a.chance) return; // 아주 낮은 확률의 보물 (#217): 원정 시드로 정해져 누가 열어도 같다
    const count = a.min + Math.floor(hash3(index, 100 + j, 53, seed) * (Math.max(a.min, a.max) - a.min + 1));
    if (count <= 0) return;
    const have = out.find((l) => l.item === a.item);
    if (have) have.count += count;
    else out.push({ item: a.item, count });
  });
  return out;
}

export type ExpeditionPhase = 'day' | 'evening' | 'night';
export const PHASE_KO: Record<ExpeditionPhase, string> = { day: '낮', evening: '저녁', night: '밤' };

/** 저녁 = 밤 시작 전 이만큼 */
export const EVENING_SEC = 90;
/** 밤이 깊어져 가장 어두워지기까지 */
export const NIGHT_FADE_SEC = 60;
/** 한밤 스카이라이트 배율 (0 이면 아무것도 안 보인다) */
export const NIGHT_SKY = 0.22;

export class ExpeditionRegistry {
  private readonly byId = new Map<string, ExpeditionDef>();
  constructor(
    readonly defs: readonly ExpeditionDef[],
    readonly rules: ExpeditionRules,
  ) {
    for (const d of defs) this.byId.set(d.id, d);
  }
  get count(): number {
    return this.defs.length;
  }
  find(id: string): ExpeditionDef | undefined {
    return this.byId.get(id);
  }
  require(id: string): ExpeditionDef {
    const d = this.byId.get(id);
    if (!d) throw new Error(`원정지 '${id}' 을(를) data/expeditions.json 에서 찾을 수 없어요`);
    return d;
  }
  /** v1 에 들어가는 원정지 (release 없음 또는 'v1'), 파일 순서 = 해제 순서 */
  v1(): ExpeditionDef[] {
    return this.defs.filter((d) => d.release === 'v1');
  }
}

/** 경과 초 → 낮/저녁/밤 */
export function phaseAt(def: Pick<ExpeditionDef, 'nightStartsAt'>, elapsedSec: number): ExpeditionPhase {
  if (def.nightStartsAt <= 0) return 'night';
  if (elapsedSec >= def.nightStartsAt) return 'night';
  if (elapsedSec >= def.nightStartsAt - EVENING_SEC) return 'evening';
  return 'day';
}

/**
 * 경과 초 → 스카이라이트 배율 0.22~1. 낮 1, 저녁 동안 0.6 까지, 밤 시작 뒤 NIGHT_FADE_SEC 동안 0.22 까지.
 * 항상 어두운 원정지(nightStartsAt 0)는 0.22 고정. 셰이더 uSkyLight 와 안개에 그대로 곱한다.
 */
export function skyLightAt(def: Pick<ExpeditionDef, 'nightStartsAt'> & { skyLight?: number | null }, elapsedSec: number): number {
  const n = def.nightStartsAt;
  if (n <= 0) return Math.max(NIGHT_SKY, def.skyLight ?? NIGHT_SKY); // 엔드는 0.5 (#162)
  if (elapsedSec <= n - EVENING_SEC) return 1;
  if (elapsedSec < n) {
    const t = (elapsedSec - (n - EVENING_SEC)) / EVENING_SEC;
    return 1 - 0.4 * t;
  }
  const t = Math.min(1, (elapsedSec - n) / NIGHT_FADE_SEC);
  return 0.6 - (0.6 - NIGHT_SKY) * t;
}

/** 남은 초 (0 아래로 안 내려감) */
export function remainingSec(def: Pick<ExpeditionDef, 'durationSec'>, elapsedSec: number): number {
  return Math.max(0, def.durationSec - elapsedSec);
}

function describePath(path: PropertyKey[], raw: unknown): string {
  if (path[0] === 'expeditions' && typeof path[1] === 'number') {
    const idx = path[1];
    const list = (raw as { expeditions?: unknown[] } | null)?.expeditions;
    const entry = Array.isArray(list) ? (list[idx] as { id?: unknown } | undefined) : undefined;
    const id = entry && typeof entry.id === 'string' ? entry.id : '?';
    const field = path[2];
    const fieldKo = typeof field === 'string' ? (FIELD_KO[field] ?? field) : '';
    return `${idx + 1}번째 원정지(id: ${id})${fieldKo ? `의 ${fieldKo}` : ''}`;
  }
  return path.map(String).join('.');
}

export function parseExpeditions(raw: unknown, fileName = 'data/expeditions.json'): ExpeditionRegistry {
  const result = ExpeditionsFile.safeParse(raw);
  if (!result.success) {
    const problems = result.error.issues.map(
      (issue) => `${describePath(issue.path, raw)}: ${koreanizeMessage(issue.message)}`,
    );
    throw new DataError(fileName, problems);
  }
  const problems: string[] = [];
  const seen = new Set<string>();
  const defs: ExpeditionDef[] = result.data.expeditions.map((e, i) => {
    const where = `${i + 1}번째 원정지(id: ${e.id})`;
    if (seen.has(e.id)) problems.push(`${where}: id 가 두 번 나와요. 하나는 이름을 바꿔 주세요`);
    seen.add(e.id);
    for (const id of Object.keys(e.wildAnimals ?? {}))
      if (!(WILD_KINDS as readonly string[]).includes(id)) problems.push(`${where}: wildAnimals 의 '${id}' 는 모르는 동물이에요 (쓸 수 있는 것: ${WILD_KINDS.join(', ')})`);
    if (e.nightStartsAt > e.durationSec) problems.push(`${where}: 밤 시작(${e.nightStartsAt}초)이 원정 시간(${e.durationSec}초)보다 늦어요`);
    if (e.nightStartsAt > 0 && e.nightStartsAt < EVENING_SEC) problems.push(`${where}: 밤 시작은 0(항상 어두움) 또는 ${EVENING_SEC}초 이상이어야 해요 (저녁 시간이 필요해요)`);
    return {
      id: e.id,
      name: e.name,
      generator: e.generator,
      durationSec: e.durationSec,
      nightStartsAt: e.nightStartsAt,
      treasures: e.treasures,
      unlockedBy: e.unlockedBy,
      nightMobs: e.nightMobs ?? [],
      wildAnimals: e.wildAnimals ?? {},
      phantoms: e.phantoms === true,
      roamers: e.roamers ?? ROAMERS_DEFAULT,
      danger: e.danger,
      materials: e.materials,
      release: e.release ?? 'v1',
      treasureBonus: e.treasureBonus ? { extraPicks: e.treasureBonus.extraPicks ?? 0, always: (e.treasureBonus.always ?? []).map((a) => ({ item: a.item, min: a.min, max: a.max, chance: a.chance ?? 1 })) } : null,
      bossId: e.boss?.id ?? null,
      skyLight: e.skyLight ?? null,
    };
  });
  if (problems.length) throw new DataError(fileName, problems);
  const { returnGraceSec, failedReturnKeepRatio, minStartMarginMin } = result.data;
  const loot = result.data.treasureChestLoot;
  for (const e of loot?.pool ?? []) if (e.max < e.min) problems.push(`보물 '${e.item}' 의 max 가 min 보다 작아요`);
  if (problems.length) throw new DataError(fileName, problems);
  return new ExpeditionRegistry(defs, { returnGraceSec, failedReturnKeepRatio, minStartMarginMin, treasureChestLoot: loot ? { picks: loot.picks, pool: loot.pool.map((e) => ({ item: e.item, min: e.min, max: e.max, weight: e.weight })) } : { picks: 0, pool: [] } });
}
