  readonly hp: number;
  /** 근접 피해 (크리퍼는 폭발 피해) */
  readonly damage: number;
  /** 칸/초 */
  readonly speed: number;
  /** 이 거리 안이면 공격(좀비) / 부풀기 시작(크리퍼) */
  readonly reach: number;
  readonly attackEveryMs: number;
  /** 크리퍼만: 부푸는 시간·폭발 반지름 */
  readonly fuseMs: number;
  readonly explodeRadius: number;
  /** 거미만: 물면 이만큼 독 (초당 1) */
  readonly poisonMs: number;
  /** 가스트만 (#161): 땅과 상관없이 사람 위 이만큼 높이에 떠서 다가온다. 없으면 걷는다 */
  readonly hover?: number;
  /** 좀비 피글린 (#161): 중립 — 누가 때리기 전엔 안 덤빈다 (맞으면 20초 화남, MobState.angryUntil) */
  readonly neutral?: boolean;
  /** 엔더 드래곤 (#162): hover 높이가 이 주기(ms)로 0 ~ hover 사이를 오르내린다 — 낮게 내려올 때 물고, 그때 칼이 닿는다 */
  readonly swoop?: number;
  /** 고릴라 (#253): 때리면 아프고 밀려난다 (눈 골렘 눈덩이의 밀림 + 피해) */
  readonly knock?: boolean;
  /** 사냥 동물 (WILD_KINDS): 맞으면 달아난다 */
  readonly flee?: boolean;
  /** 사냥 동물 (WILD_KINDS): 이 거리(칸) 안에 사람이 오면 먼저 덤빈다 */
  readonly aggroR?: number;
  /** 물고기 (연어, 2026-11-06): 물 칸 안에서만 헤엄친다 — 땅에 안 올라오고, 깊이 2칸 이상인 물에 산다 */
  readonly swim?: boolean;
  /** 복어 (2026-11-06): 사람이 PUFF_R 칸 안에 오면 부풀고(state = attack), 부푼 채 닿으면 따끔 + 독 */
  readonly puff?: boolean;
  /** 이 아이템을 들고 탭하면 CALM_MS 동안 먼저 덤비지 않는다 (코뿔소 = 밀, 아나콘다 = 생 닭고기, 2026-11-06). 때리면 다시 화난다 */
  readonly calmWith?: string | readonly string[];
  /** 호랑이 (2026-11-06): 몰래 천천히 다가오다 이 거리(칸) 안이면 덮친다(3배 빠르게) */
  readonly pounce?: number;
