/** 바뀌면 옛 클라에 '새로고침해 주세요'. 2: 몹 체력 2바이트 (#254 — 거대 고릴라 400·거대 워든 500·엔더 드래곤 300 이 255 로 잘렸다) */
export const PROTOCOL_VERSION = 2;

/** 바이너리 메시지 종류 (첫 바이트) */
export const MSG = {
  /** C→S 20Hz */
  PlayerMove: 0x01,
  /** S→C 20Hz */
  PlayersState: 0x02,
  /** C→S 블록 놓기·부수기 요청 */
  BlockChangeReq: 0x10,
  /** S→C 확정된 블록 변경 (누가) */
  BlockChanged: 0x11,
  /** S→C 요청 거절 → 클라는 되돌린다 */
  BlockChangeRejected: 0x12,
  /** S→C 서버가 바꾼 블록 묶음 (액체 흐름 등) */
  BlockBatch: 0x13,
  /** S→C 가방 칸 바뀜 (M4) */
  InvSlots: 0x14,
  /** C→S 가방 칸 옮기기 */
  InvMove: 0x15,
  /** C→S 버리기 (사라짐) */
  InvDrop: 0x16,
  /** S→C 입장 시 저장된 청크 (blob) */
  ChunkData: 0x20,
  /** S→C 원정 중 1Hz: 경과·전체 초, 낮/저녁/밤 */
  ExpeditionTimer: 0x30,
  /** 양방향 채팅: 이모지·문구 번호만 (규칙 3). C→S 는 idx 무시 */
  Emote: 0x40,
  /** 경험치를 얻었다 (M6-1) S→C */
  XpGained: 0x52,
  /** 경험치 총량 정정 S→C */
  XpState: 0x53,
  /** S→C 20Hz 원정 몹 상태 (M7-2) */
  MobsState: 0x60,
  Ping: 0x7f,
  Pong: 0x7e,
} as const;

